import json
from pathlib import Path
root = Path('docs/agent-program/kiana-completion')
program = json.loads((root / 'program.json').read_text())
tasks = []
for path in sorted((root / 'tasks').glob('*.json')):
    tasks.extend(json.loads(path.read_text())['tasks'])
by_id = {task['task_id']: task for task in tasks}
domains = {d['domain_id']: d for d in json.loads((root / 'domains.json').read_text())['domains']}
ownership = {p['id'] for p in json.loads((root / 'ownership.json').read_text())['packages']}
gates = json.loads((root / 'dags/gates.json').read_text())
verification = json.loads((root / 'acceptance/verification-gates.json').read_text())
capability_ids = {json.loads(line)['capability_id'] for line in (root / 'capability-ledger.jsonl').read_text().splitlines() if line}
assert len(tasks) == program['counts']['total_tasks'] == 170
assert len(by_id) == 170
assert len(domains) == program['counts']['domains'] == 18
assert len(ownership) == program['counts']['ownership_packages'] == 30
assert gates['task_catalog']['expected_tasks_by_wave'] == {wave: sum(1 for t in tasks if t['wave'] == wave) for wave in [f'W{i}' for i in range(7)]}
assert verification['gate_order'] == ['focused', 'domain', 'integration', 'commercial']
wave_rank = {f'W{i}': i for i in range(7)}
visiting = set(); visited = set()
def visit(task_id):
    if task_id in visiting:
        raise AssertionError(f'cycle at {task_id}')
    if task_id in visited:
        return
    visiting.add(task_id)
    for dependency in by_id[task_id]['depends_on']:
        assert dependency in by_id, (task_id, dependency)
        assert wave_rank[by_id[dependency]['wave']] <= wave_rank[by_id[task_id]['wave']], (task_id, dependency)
        visit(dependency)
    visiting.remove(task_id); visited.add(task_id)
for task in tasks:
    assert set(task['ownership_packages']) <= ownership, task['task_id']
    assert task['required_artifacts'], task['task_id']
    if task['domain_id'] != 'GLOBAL':
        assert task['reference_capabilities'] and set(task['reference_capabilities']) <= capability_ids, task['task_id']
    if task['requires_approval']:
        assert task['required_approvals'], task['task_id']
    visit(task['task_id'])
print('catalog_ok tasks=170 acyclic=true ownership=true gates=true')
